// Bundled Pedagogical Examples for Offline 1-Click Loading
export const EXAMPLES_DATA = {
  "01_stdio.c": "/*\n * 01_stdio.c - Standard I/O Interactive Program\n *\n * Demonstrates:\n * - Interactive console standard I/O (printf, scanf, fgets)\n * - Input validation and basic computation\n *\n * Compilation in IDE Terminal:\n *   gcc 01_stdio.c -o a.out\n *   ./a.out\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n\nvoid show_menu(void) {\n    printf(\"\\n========================================\\n\");\n    printf(\"   Interactive C Math & Text Console    \\n\");\n    printf(\"========================================\\n\");\n    printf(\"1. Calculate Fibonacci sequence\\n\");\n    printf(\"2. Compute Factorial\\n\");\n    printf(\"3. Prime number tester\\n\");\n    printf(\"4. Exit\\n\");\n    printf(\"Enter choice (1-4): \");\n    fflush(stdout);\n}\n\nvoid fibonacci(void) {\n    int n;\n    printf(\"\\n[Fibonacci] Enter number of terms (1-30): \");\n    fflush(stdout);\n    if (scanf(\"%d\", &n) != 1 || n < 1 || n > 30) {\n        printf(\"Invalid input! Please enter a number between 1 and 30.\\n\");\n        return;\n    }\n\n    long long a = 0, b = 1;\n    printf(\"Fibonacci sequence: \");\n    for (int i = 0; i < n; i++) {\n        printf(\"%lld \", a);\n        long long next = a + b;\n        a = b;\n        b = next;\n    }\n    printf(\"\\n\");\n}\n\nvoid factorial(void) {\n    int n;\n    printf(\"\\n[Factorial] Enter a non-negative integer (0-15): \");\n    fflush(stdout);\n    if (scanf(\"%d\", &n) != 1 || n < 0 || n > 15) {\n        printf(\"Invalid input! Please enter a number between 0 and 15.\\n\");\n        return;\n    }\n\n    long long fact = 1;\n    for (int i = 1; i <= n; i++) {\n        fact *= i;\n    }\n    printf(\"%d! = %lld\\n\", n, fact);\n}\n\nvoid prime_check(void) {\n    int n;\n    printf(\"\\n[Prime Check] Enter an integer >= 2: \");\n    fflush(stdout);\n    if (scanf(\"%d\", &n) != 1 || n < 2) {\n        printf(\"Invalid input! Please enter a number >= 2.\\n\");\n        return;\n    }\n\n    int is_prime = 1;\n    for (int i = 2; i * i <= n; i++) {\n        if (n % i == 0) {\n            is_prime = 0;\n            break;\n        }\n    }\n\n    if (is_prime) {\n        printf(\"%d is a PRIME number!\\n\", n);\n    } else {\n        printf(\"%d is NOT a prime number (composite).\\n\", n);\n    }\n}\n\nint main(void) {\n    // Disable stdout buffering so prompts without trailing newline display immediately\n    setbuf(stdout, NULL);\n\n    char name[64];\n    printf(\"Welcome to the In-Browser C/C++ IDE!\\n\");\n    printf(\"Please enter your name: \");\n    fflush(stdout);\n    if (scanf(\"%63s\", name) != 1) {\n        return 0;\n    }\n\n    printf(\"Hello, %s! Let's run some interactive computations.\\n\", name);\n\n    int choice = 0;\n    while (1) {\n        show_menu();\n        if (scanf(\"%d\", &choice) != 1) {\n            printf(\"\\nExiting. Goodbye, %s!\\n\", name);\n            break;\n        }\n\n        switch (choice) {\n            case 1: fibonacci(); break;\n            case 2: factorial(); break;\n            case 3: prime_check(); break;\n            case 4:\n                printf(\"\\nExiting. Goodbye, %s!\\n\", name);\n                return 0;\n            default:\n                printf(\"Invalid selection! Please choose an option 1-4.\\n\");\n        }\n    }\n\n    return 0;\n}\n",
  "02_raylib_interactive.c": "/*\n * 02_raylib_interactive.c - Interactive Raylib 5.5 Graphics Program\n *\n * Demonstrates:\n * - Hardware-accelerated WebGL graphics via Raylib 5.5\n * - Keyboard input: WASD / Arrow keys for movement, Space bar for color pulse\n * - Mouse input: Cursor tracking, left click to place particle bursts\n * - Smooth frame pacing at 60 FPS\n *\n * Prerequisites:\n *   In IDE Project Settings, ensure \"Enable Raylib\" is ON.\n *\n * Compilation in IDE Terminal:\n *   gcc 02_raylib_interactive.c -lraylib -o a.out\n *   ./a.out\n */\n\n#include \"raylib.h\"\n#include <math.h>\n\n#define MAX_PARTICLES 64\n\ntypedef struct {\n    Vector2 position;\n    Vector2 velocity;\n    Color color;\n    float alpha;\n    float radius;\n    bool active;\n} Particle;\n\nint main(void) {\n    const int screenWidth = 800;\n    const int screenHeight = 450;\n\n    InitWindow(screenWidth, screenHeight, \"Raylib Interactive Playground\");\n    SetTargetFPS(60);\n\n    // Player state\n    Vector2 playerPos = { (float)screenWidth / 2.0f, (float)screenHeight / 2.0f };\n    float playerRadius = 24.0f;\n    float playerSpeed = 5.0f;\n    Color playerColor = SKYBLUE;\n\n    // Particle burst array\n    Particle particles[MAX_PARTICLES] = { 0 };\n\n    while (!WindowShouldClose()) {\n        // --- 1. Keyboard Input Handling ---\n        if (IsKeyDown(KEY_RIGHT) || IsKeyDown(KEY_D)) playerPos.x += playerSpeed;\n        if (IsKeyDown(KEY_LEFT) || IsKeyDown(KEY_A))  playerPos.x -= playerSpeed;\n        if (IsKeyDown(KEY_DOWN) || IsKeyDown(KEY_S))  playerPos.y += playerSpeed;\n        if (IsKeyDown(KEY_UP) || IsKeyDown(KEY_W))    playerPos.y -= playerSpeed;\n\n        // Keep player inside screen boundaries\n        if (playerPos.x < playerRadius) playerPos.x = playerRadius;\n        if (playerPos.x > screenWidth - playerRadius) playerPos.x = screenWidth - playerRadius;\n        if (playerPos.y < playerRadius) playerPos.y = playerRadius;\n        if (playerPos.y > screenHeight - playerRadius) playerPos.y = screenHeight - playerRadius;\n\n        // Space bar changes player color\n        if (IsKeyPressed(KEY_SPACE)) {\n            playerColor = (Color){ (unsigned char)GetRandomValue(80, 255),\n                                   (unsigned char)GetRandomValue(80, 255),\n                                   (unsigned char)GetRandomValue(80, 255), 255 };\n        }\n\n        // --- 2. Mouse Input Handling ---\n        Vector2 mousePos = GetMousePosition();\n\n        if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT)) {\n            // Spawn particle burst at mouse position\n            for (int i = 0; i < 16; i++) {\n                for (int p = 0; p < MAX_PARTICLES; p++) {\n                    if (!particles[p].active) {\n                        particles[p].active = true;\n                        particles[p].position = mousePos;\n                        float angle = (float)GetRandomValue(0, 360) * (PI / 180.0f);\n                        float speed = (float)GetRandomValue(2, 6);\n                        particles[p].velocity = (Vector2){ cosf(angle) * speed, sinf(angle) * speed };\n                        particles[p].radius = (float)GetRandomValue(4, 10);\n                        particles[p].alpha = 1.0f;\n                        particles[p].color = playerColor;\n                        break;\n                    }\n                }\n            }\n        }\n\n        // Update active particles\n        for (int i = 0; i < MAX_PARTICLES; i++) {\n            if (particles[i].active) {\n                particles[i].position.x += particles[i].velocity.x;\n                particles[i].position.y += particles[i].velocity.y;\n                particles[i].alpha -= 0.025f;\n                if (particles[i].alpha <= 0.0f) {\n                    particles[i].active = false;\n                }\n            }\n        }\n\n        // --- 3. Rendering ---\n        BeginDrawing();\n            ClearBackground((Color){ 24, 24, 28, 255 });\n\n            // Draw grid pattern in background\n            for (int x = 0; x < screenWidth; x += 40) {\n                DrawLine(x, 0, x, screenHeight, (Color){ 36, 36, 42, 255 });\n            }\n            for (int y = 0; y < screenHeight; y += 40) {\n                DrawLine(0, y, screenWidth, y, (Color){ 36, 36, 42, 255 });\n            }\n\n            // Draw line connecting player and mouse\n            DrawLineEx(playerPos, mousePos, 2.0f, Fade(LIGHTGRAY, 0.4f));\n\n            // Draw mouse reticle\n            DrawCircleLines((int)mousePos.x, (int)mousePos.y, 12, Fade(YELLOW, 0.8f));\n            DrawCircle((int)mousePos.x, (int)mousePos.y, 3, YELLOW);\n\n            // Draw particles\n            for (int i = 0; i < MAX_PARTICLES; i++) {\n                if (particles[i].active) {\n                    DrawCircleV(particles[i].position, particles[i].radius, Fade(particles[i].color, particles[i].alpha));\n                }\n            }\n\n            // Draw player\n            DrawCircleV(playerPos, playerRadius + 4, Fade(playerColor, 0.3f));\n            DrawCircleV(playerPos, playerRadius, playerColor);\n            DrawCircleLines((int)playerPos.x, (int)playerPos.y, playerRadius, RAYWHITE);\n\n            // UI Overlay & Instructions\n            DrawRectangle(10, 10, 310, 100, Fade(BLACK, 0.6f));\n            DrawRectangleLines(10, 10, 310, 100, DARKGRAY);\n            DrawText(\"Raylib 5.5 Interactive Demo\", 20, 18, 18, RAYWHITE);\n            DrawText(\"- WASD / Arrows: Move player circle\", 20, 42, 13, LIGHTGRAY);\n            DrawText(\"- Space: Change player color\", 20, 60, 13, LIGHTGRAY);\n            DrawText(\"- Left Click: Spawn particle burst\", 20, 78, 13, LIGHTGRAY);\n\n            DrawFPS(screenWidth - 90, 15);\n        EndDrawing();\n    }\n\n    CloseWindow();\n    return 0;\n}\n",
  "03_framebuffer_graphics.c": "/*\n * 03_framebuffer_graphics.c - Software Framebuffer Direct Pixel Program\n *\n * Demonstrates:\n * - Direct memory pixel buffer manipulation using <graphics.h>\n * - Real-time 60 FPS procedural plasma effect calculated per-pixel\n * - Interactive mouse drawing directly into pixel memory with persistent canvas layer\n * - Zero external dependencies; compiles in pure standard C without link flags!\n *\n * Controls:\n * - Mouse Move: Glowing cursor indicator follows pointer in real time\n * - Left Click & Drag: Paint glowing strokes onto the persistent canvas\n * - Press 'C' or Space: Clear painted strokes\n * - Press Left / Right Arrow: Slow down / speed up plasma animation\n *\n * Compilation in IDE Terminal:\n *   gcc 03_framebuffer_graphics.c -o a.out\n *   ./a.out\n */\n\n#include <graphics.h>\n#include <stdint.h>\n#include <stdlib.h>\n#include <string.h>\n#include <stdio.h>\n#include <math.h>\n\n#define WIDTH  320\n#define HEIGHT 240\n\n// 32-bit RGBA pixel helper (0xAABBGGRR in little-endian)\nstatic inline uint32_t make_rgba(uint8_t r, uint8_t g, uint8_t b, uint8_t a) {\n    return ((uint32_t)a << 24) | ((uint32_t)b << 16) | ((uint32_t)g << 8) | (uint32_t)r;\n}\n\n// Draw a filled circle directly into a pixel buffer\nstatic void draw_brush(uint32_t *buf, int cx, int cy, int radius, uint32_t color) {\n    int r2 = radius * radius;\n    for (int dy = -radius; dy <= radius; dy++) {\n        int py = cy + dy;\n        if (py < 0 || py >= HEIGHT) continue;\n        for (int dx = -radius; dx <= radius; dx++) {\n            int px = cx + dx;\n            if (px < 0 || px >= WIDTH) continue;\n            if (dx * dx + dy * dy <= r2) {\n                buf[py * WIDTH + px] = color;\n            }\n        }\n    }\n}\n\n// Draw a distinct glowing cursor indicator\nstatic void draw_cursor(uint32_t *pixels, int cx, int cy) {\n    if (cx < 0 || cx >= WIDTH || cy < 0 || cy >= HEIGHT) return;\n\n    // Draw bright yellow core\n    draw_brush(pixels, cx, cy, 3, make_rgba(255, 255, 0, 255));\n\n    // Draw outer outline ring\n    int ringRadius = 6;\n    int r2_inner = (ringRadius - 1) * (ringRadius - 1);\n    int r2_outer = ringRadius * ringRadius;\n    for (int dy = -ringRadius; dy <= ringRadius; dy++) {\n        int py = cy + dy;\n        if (py < 0 || py >= HEIGHT) continue;\n        for (int dx = -ringRadius; dx <= ringRadius; dx++) {\n            int px = cx + dx;\n            if (px < 0 || px >= WIDTH) continue;\n            int d2 = dx * dx + dy * dy;\n            if (d2 >= r2_inner && d2 <= r2_outer) {\n                pixels[py * WIDTH + px] = make_rgba(0, 0, 0, 255); // Black outline\n            }\n        }\n    }\n}\n\nint main(void) {\n    printf(\"Starting Software Framebuffer Graphics Demo (320x240 @ 60 FPS)...\\n\");\n    printf(\"Controls:\\n\");\n    printf(\" - Move Mouse: Cursor follows pointer\\n\");\n    printf(\" - Left Click & Drag: Paint persistent white strokes\\n\");\n    printf(\" - Press 'C' or Space: Clear painted strokes\\n\");\n    printf(\" - Press Left/Right Arrow: Adjust animation speed\\n\\n\");\n\n    graphics_init(WIDTH, HEIGHT, \"Software Framebuffer Plasma & Paint\");\n\n    uint32_t *pixels = (uint32_t*)malloc(WIDTH * HEIGHT * sizeof(uint32_t));\n    uint32_t *paintCanvas = (uint32_t*)calloc(WIDTH * HEIGHT, sizeof(uint32_t));\n    if (!pixels || !paintCanvas) {\n        if (pixels) free(pixels);\n        if (paintCanvas) free(paintCanvas);\n        return 1;\n    }\n\n    // Precompute 512-entry sine lookup table for fluid 60 FPS performance\n    static float sinTab[512];\n    for (int i = 0; i < 512; i++) {\n        sinTab[i] = sinf(((float)i / 512.0f) * 6.2831853f);\n    }\n\n    float time = 0.0f;\n    int mouseX = -1, mouseY = -1, buttons = 0, wheel = 0;\n\n    while (!graphics_should_close()) {\n        // Poll mouse state\n        graphics_get_mouse(&mouseX, &mouseY, &buttons, &wheel);\n\n        // Check if user pressed 'C' (67) or Space (32) to clear canvas\n        if (graphics_is_key_down('C') || graphics_is_key_down('c') || graphics_is_key_down(32)) {\n            memset(paintCanvas, 0, WIDTH * HEIGHT * sizeof(uint32_t));\n        }\n\n        // Adjust animation speed with arrow keys\n        float timeSpeed = 0.05f;\n        if (graphics_is_key_down(262)) timeSpeed = 0.15f; // Right Arrow accelerates\n        if (graphics_is_key_down(263)) timeSpeed = 0.01f; // Left Arrow slows down\n\n        time += timeSpeed;\n        int tOffset = (int)(time * 60.0f);\n\n        // Render animated procedural plasma into pixel memory using lookup table\n        for (int y = 0; y < HEIGHT; y++) {\n            int rowOffset = y * WIDTH;\n            int yIdx = (y * 3 + tOffset) & 511;\n            float v2 = sinTab[yIdx];\n\n            for (int x = 0; x < WIDTH; x++) {\n                int xIdx = (x * 3 + tOffset) & 511;\n                int diagIdx = ((x + y) * 2 - tOffset) & 511;\n                float v1 = sinTab[xIdx];\n                float v3 = sinTab[diagIdx];\n\n                float val = (v1 + v2 + v3) * 0.333f; // -1.0 to 1.0\n\n                // Vivid color mapping\n                uint8_t r = (uint8_t)((val + 1.0f) * 0.5f * 255.0f);\n                uint8_t g = (uint8_t)((sinTab[(xIdx + yIdx) & 511] + 1.0f) * 0.5f * 255.0f);\n                uint8_t b = (uint8_t)((1.0f - (val + 1.0f) * 0.5f) * 255.0f);\n\n                pixels[rowOffset + x] = make_rgba(r, g, b, 255);\n            }\n        }\n\n        // Interactive mouse painting: If left button clicked or dragged, paint onto persistent canvas\n        if ((buttons & 1) && mouseX >= 0 && mouseX < WIDTH && mouseY >= 0 && mouseY < HEIGHT) {\n            draw_brush(paintCanvas, mouseX, mouseY, 10, make_rgba(255, 255, 255, 255));\n        }\n\n        // Blend persistent paint canvas layer on top of plasma\n        for (int i = 0; i < WIDTH * HEIGHT; i++) {\n            if (paintCanvas[i] != 0) {\n                pixels[i] = paintCanvas[i];\n            }\n        }\n\n        // Render hover cursor on top if mouse is inside the canvas\n        if (mouseX >= 0 && mouseX < WIDTH && mouseY >= 0 && mouseY < HEIGHT) {\n            draw_cursor(pixels, mouseX, mouseY);\n        }\n\n        // Present pixel buffer to the graphics display\n        graphics_present(pixels);\n\n        // Synchronize at 60 FPS\n        graphics_wait_frame(60);\n    }\n\n    free(paintCanvas);\n    free(pixels);\n    graphics_close();\n    return 0;\n}\n",
  "04_canvas_vector.c": "/*\n * 04_canvas_vector.c - HTML5 2D Vector Canvas Graphics Program\n *\n * Demonstrates:\n * - High-level 2D vector graphics using <graphics_canvas.h>\n * - Native browser Canvas 2D rendering (anti-aliased shapes, arcs, text, transforms)\n * - Rotating matrix transform shapes (canvas_save, canvas_rotate, canvas_restore)\n * - Multiple bouncing balls with physics simulation\n * - Interactive mouse tracking and vector lines\n * - Zero external libraries; compiles in pure standard C without link flags!\n *\n * Compilation in IDE Terminal:\n *   gcc 04_canvas_vector.c -o a.out\n *   ./a.out\n */\n\n#include <graphics_canvas.h>\n#include <math.h>\n\n#define WIDTH  640\n#define HEIGHT 480\n#define NUM_BALLS 8\n\ntypedef struct {\n    float x, y;\n    float vx, vy;\n    float radius;\n    const char *color;\n} Ball;\n\nint main(void) {\n    graphics_init(WIDTH, HEIGHT, \"HTML5 2D Vector Canvas Demo\");\n\n    Ball balls[NUM_BALLS] = {\n        { 100, 150,  3.2f,  2.5f, 20.0f, \"#ff4d4f\" },\n        { 200, 220, -2.8f,  3.1f, 24.0f, \"#40a9ff\" },\n        { 300, 100,  3.5f, -2.2f, 18.0f, \"#73d13d\" },\n        { 400, 300, -2.0f,  3.8f, 28.0f, \"#ffa940\" },\n        { 150, 350,  4.0f,  1.8f, 16.0f, \"#9254de\" },\n        { 450, 180, -3.1f, -2.7f, 22.0f, \"#f759ab\" },\n        { 250, 280,  2.5f, -3.4f, 26.0f, \"#36cfc9\" },\n        { 350, 380, -3.8f,  2.0f, 19.0f, \"#ffec3d\" },\n    };\n\n    float rotation = 0.0f;\n    int mouseX = 0, mouseY = 0, buttons = 0, wheel = 0;\n\n    while (!graphics_should_close()) {\n        // Poll mouse state\n        graphics_get_mouse(&mouseX, &mouseY, &buttons, &wheel);\n\n        // Update physics\n        for (int i = 0; i < NUM_BALLS; i++) {\n            balls[i].x += balls[i].vx;\n            balls[i].y += balls[i].vy;\n\n            // Bounce off left/right walls\n            if (balls[i].x - balls[i].radius < 0) {\n                balls[i].x = balls[i].radius;\n                balls[i].vx = -balls[i].vx;\n            } else if (balls[i].x + balls[i].radius > WIDTH) {\n                balls[i].x = WIDTH - balls[i].radius;\n                balls[i].vx = -balls[i].vx;\n            }\n\n            // Bounce off top/bottom walls\n            if (balls[i].y - balls[i].radius < 0) {\n                balls[i].y = balls[i].radius;\n                balls[i].vy = -balls[i].vy;\n            } else if (balls[i].y + balls[i].radius > HEIGHT) {\n                balls[i].y = HEIGHT - balls[i].radius;\n                balls[i].vy = -balls[i].vy;\n            }\n        }\n\n        rotation += 0.02f;\n\n        // --- 1. Clear & Background ---\n        canvas_set_fill_style(\"#141416\");\n        canvas_fill_rect(0, 0, WIDTH, HEIGHT);\n\n        // --- 2. Rotating Vector Star in Center ---\n        canvas_save();\n        canvas_translate(WIDTH / 2.0f, HEIGHT / 2.0f);\n        canvas_rotate(rotation);\n\n        canvas_set_line_width(3.0f);\n        canvas_set_stroke_style(\"rgba(255, 255, 255, 0.15)\");\n        for (int i = 0; i < 8; i++) {\n            canvas_rotate(3.14159f / 4.0f);\n            canvas_stroke_rect(-60, -60, 120, 120);\n        }\n        canvas_restore();\n\n        // --- 3. Interactive Vector Lines to Mouse ---\n        if (mouseX > 0 && mouseX < WIDTH && mouseY > 0 && mouseY < HEIGHT) {\n            canvas_set_line_width(1.5f);\n            for (int i = 0; i < NUM_BALLS; i++) {\n                float dx = balls[i].x - mouseX;\n                float dy = balls[i].y - mouseY;\n                float dist = sqrtf(dx * dx + dy * dy);\n                if (dist < 180.0f) {\n                    canvas_begin_path();\n                    canvas_move_to(mouseX, mouseY);\n                    canvas_line_to(balls[i].x, balls[i].y);\n                    canvas_set_stroke_style(\"rgba(255, 255, 255, 0.35)\");\n                    canvas_stroke();\n                }\n            }\n\n            // Draw glowing cursor ring\n            canvas_begin_path();\n            canvas_arc(mouseX, mouseY, 12.0f, 0, 6.283f, false);\n            canvas_set_stroke_style(\"#52c41a\");\n            canvas_set_line_width(2.0f);\n            canvas_stroke();\n        }\n\n        // --- 4. Render Bouncing Balls ---\n        for (int i = 0; i < NUM_BALLS; i++) {\n            canvas_begin_path();\n            canvas_arc(balls[i].x, balls[i].y, balls[i].radius, 0, 6.283f, false);\n            canvas_set_fill_style(balls[i].color);\n            canvas_fill();\n\n            // Ball outline\n            canvas_set_line_width(2.0f);\n            canvas_set_stroke_style(\"#ffffff\");\n            canvas_stroke();\n        }\n\n        // --- 5. Typography / HUD ---\n        canvas_set_fill_style(\"rgba(0, 0, 0, 0.55)\");\n        canvas_fill_rect(10, 10, 320, 85);\n        canvas_set_stroke_style(\"#333333\");\n        canvas_stroke_rect(10, 10, 320, 85);\n\n        canvas_set_font(\"bold 16px sans-serif\");\n        canvas_set_fill_style(\"#ffffff\");\n        canvas_fill_text(\"HTML5 Canvas 2D Vector Demo\", 20, 34);\n\n        canvas_set_font(\"13px sans-serif\");\n        canvas_set_fill_style(\"#aaaaaa\");\n        canvas_fill_text(\"Rendering via OffscreenCanvas 2D context\", 20, 56);\n        canvas_fill_text(\"Move mouse over canvas to connect nodes\", 20, 76);\n\n        // Present vector frame\n        canvas_present();\n\n        // 60 FPS pacing\n        graphics_wait_frame(60);\n    }\n\n    graphics_close();\n    return 0;\n}\n",
  "05_canvas_pixels.c": "/*\n * 05_canvas_pixels.c - HTML5 Canvas Pixel-Level Manipulation & 2D Image Processing\n *\n * Demonstrates:\n * - Direct pixel-level framebuffer access from Canvas 2D using <graphics_canvas.h>\n * - canvas_get_pixels() / canvas_put_pixels() full framebuffer transfer\n * - canvas_get_image_data() / canvas_put_image_data() sub-rectangle transfer\n * - canvas_get_pixel() / canvas_set_pixel() single-pixel inspection and writing\n * - 2D Image Processing filters in pure C:\n *     1. 3x3 Sobel Edge Detection filter (horizontal/vertical gradient convolution)\n *     2. 3x3 Box Blur spatial convolution\n *     3. Grayscale & Contrast adjustment\n *     4. Color Inversion\n *     5. Interactive Lens / Spotlight tracking mouse cursor\n * - Hybrid rendering pipeline: Vector Scene -> Pixel Filter -> Vector HUD Overlay\n * - Zero external libraries; compiles in pure standard C without link flags!\n *\n * Compilation in IDE Terminal:\n *   gcc 05_canvas_pixels.c -o a.out\n *   ./a.out\n */\n\n#include <graphics_canvas.h>\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <math.h>\n\n#define WIDTH  320\n#define HEIGHT 240\n#define TOTAL_PIXELS (WIDTH * HEIGHT)\n\n// Framebuffers for pixel manipulation\nstatic uint32_t src_pixels[TOTAL_PIXELS];\nstatic uint32_t dst_pixels[TOTAL_PIXELS];\n\n// Pixel color unpacking & packing helpers (RGBA 32-bit little-endian)\n#define PIXEL_R(p) ((uint8_t)((p) & 0xFF))\n#define PIXEL_G(p) ((uint8_t)(((p) >> 8) & 0xFF))\n#define PIXEL_B(p) ((uint8_t)(((p) >> 16) & 0xFF))\n#define PIXEL_A(p) ((uint8_t)(((p) >> 24) & 0xFF))\n#define PACK_RGBA(r, g, b, a) \\\n    (((uint32_t)(uint8_t)(a) << 24) | \\\n     ((uint32_t)(uint8_t)(b) << 16) | \\\n     ((uint32_t)(uint8_t)(g) << 8)  | \\\n      (uint32_t)(uint8_t)(r))\n\n// Clamp helper\nstatic inline int clamp_int(int val, int min, int max) {\n    if (val < min) return min;\n    if (val > max) return max;\n    return val;\n}\n\n// -------------------------------------------------------------\n// 2D Image Processing Filters\n// -------------------------------------------------------------\n\n// Mode 1: Grayscale & Contrast\nstatic void filter_grayscale(const uint32_t *src, uint32_t *dst) {\n    for (int i = 0; i < TOTAL_PIXELS; i++) {\n        uint32_t p = src[i];\n        int r = PIXEL_R(p);\n        int g = PIXEL_G(p);\n        int b = PIXEL_B(p);\n        // Standard Rec. 601 luma coefficients\n        int gray = (r * 77 + g * 150 + b * 29) >> 8;\n        // Contrast enhancement\n        gray = clamp_int((gray - 128) * 13 / 10 + 128, 0, 255);\n        dst[i] = PACK_RGBA(gray, gray, gray, 255);\n    }\n}\n\n// Mode 2: 3x3 Box Blur (Spatial Convolution)\nstatic void filter_box_blur(const uint32_t *src, uint32_t *dst) {\n    for (int y = 0; y < HEIGHT; y++) {\n        for (int x = 0; x < WIDTH; x++) {\n            if (x == 0 || x == WIDTH - 1 || y == 0 || y == HEIGHT - 1) {\n                dst[y * WIDTH + x] = src[y * WIDTH + x];\n                continue;\n            }\n            int r_sum = 0, g_sum = 0, b_sum = 0;\n            for (int dy = -1; dy <= 1; dy++) {\n                for (int dx = -1; dx <= 1; dx++) {\n                    uint32_t p = src[(y + dy) * WIDTH + (x + dx)];\n                    r_sum += PIXEL_R(p);\n                    g_sum += PIXEL_G(p);\n                    b_sum += PIXEL_B(p);\n                }\n            }\n            dst[y * WIDTH + x] = PACK_RGBA(r_sum / 9, g_sum / 9, b_sum / 9, 255);\n        }\n    }\n}\n\n// Mode 3: 3x3 Sobel Edge Detection (Gradient Convolution)\nstatic void filter_sobel(const uint32_t *src, uint32_t *dst) {\n    static const int gx_mat[3][3] = {\n        { -1, 0, 1 },\n        { -2, 0, 2 },\n        { -1, 0, 1 }\n    };\n    static const int gy_mat[3][3] = {\n        { -1, -2, -1 },\n        {  0,  0,  0 },\n        {  1,  2,  1 }\n    };\n\n    for (int y = 0; y < HEIGHT; y++) {\n        for (int x = 0; x < WIDTH; x++) {\n            if (x == 0 || x == WIDTH - 1 || y == 0 || y == HEIGHT - 1) {\n                dst[y * WIDTH + x] = PACK_RGBA(0, 0, 0, 255);\n                continue;\n            }\n\n            int gx = 0, gy = 0;\n            for (int dy = -1; dy <= 1; dy++) {\n                for (int dx = -1; dx <= 1; dx++) {\n                    uint32_t p = src[(y + dy) * WIDTH + (x + dx)];\n                    int luma = (PIXEL_R(p) * 77 + PIXEL_G(p) * 150 + PIXEL_B(p) * 29) >> 8;\n                    gx += luma * gx_mat[dy + 1][dx + 1];\n                    gy += luma * gy_mat[dy + 1][dx + 1];\n                }\n            }\n\n            int mag = abs(gx) + abs(gy);\n            mag = clamp_int(mag, 0, 255);\n\n            // Colorize edges: Cyan to White intensity\n            uint8_t er = (uint8_t)(mag > 180 ? mag : mag / 3);\n            uint8_t eg = (uint8_t)mag;\n            uint8_t eb = (uint8_t)mag;\n            dst[y * WIDTH + x] = PACK_RGBA(er, eg, eb, 255);\n        }\n    }\n}\n\n// Mode 4: Invert Colors\nstatic void filter_invert(const uint32_t *src, uint32_t *dst) {\n    for (int i = 0; i < TOTAL_PIXELS; i++) {\n        uint32_t p = src[i];\n        dst[i] = PACK_RGBA(255 - PIXEL_R(p), 255 - PIXEL_G(p), 255 - PIXEL_B(p), 255);\n    }\n}\n\n// -------------------------------------------------------------\n// Interactive Spotlight / Lens Application\n// -------------------------------------------------------------\nstatic void apply_lens(const uint32_t *base, const uint32_t *filtered, uint32_t *out, int mx, int my, int radius) {\n    int r2 = radius * radius;\n    for (int y = 0; y < HEIGHT; y++) {\n        for (int x = 0; x < WIDTH; x++) {\n            int idx = y * WIDTH + x;\n            int dx = x - mx;\n            int dy = y - my;\n            int dist2 = dx * dx + dy * dy;\n\n            if (dist2 <= r2) {\n                // Inside lens: show filtered pixel\n                out[idx] = filtered[idx];\n            } else if (dist2 <= r2 + 2 * radius) {\n                // Lens border: bright white ring\n                out[idx] = PACK_RGBA(255, 255, 255, 255);\n            } else {\n                // Outside lens: normal base pixel\n                out[idx] = base[idx];\n            }\n        }\n    }\n}\n\n// Filter mode names\nstatic const char *MODE_NAMES[] = {\n    \"Interactive Lens (Sobel)\",\n    \"Interactive Lens (Blur)\",\n    \"Full Screen: Sobel Edges\",\n    \"Full Screen: 3x3 Box Blur\",\n    \"Full Screen: Grayscale\",\n    \"Full Screen: Color Invert\",\n    \"Sub-rect ImageData Demo\"\n};\n#define NUM_MODES 7\n\nint main(void) {\n    graphics_init(WIDTH, HEIGHT, \"Canvas 2D Pixel Manipulation & Image Processing\");\n\n    int mode = 0;\n    int last_button = 0;\n    float time_sec = 0.0f;\n    int mouseX = WIDTH / 2, mouseY = HEIGHT / 2, buttons = 0, wheel = 0;\n\n    printf(\"=== HTML5 Canvas 2D Pixel Processing Demo ===\\n\");\n    printf(\"Controls:\\n\");\n    printf(\"  - Mouse Click / Space: Cycle Image Processing Modes\\n\");\n    printf(\"  - Move Mouse: Move interactive filter spotlight lens\\n\");\n    printf(\"  - Keys 1-7: Switch directly to mode 1 through 7\\n\");\n\n    while (!graphics_should_close()) {\n        time_sec += 0.03f;\n\n        // Poll mouse input\n        graphics_get_mouse(&mouseX, &mouseY, &buttons, &wheel);\n\n        // Click to cycle mode\n        int click_down = (buttons & 1);\n        if (click_down && !last_button) {\n            mode = (mode + 1) % NUM_MODES;\n        }\n        last_button = click_down;\n\n        // Number keys 1-7 (Keycodes 49..55)\n        for (int k = 0; k < NUM_MODES; k++) {\n            if (graphics_is_key_down(49 + k)) {\n                mode = k;\n            }\n        }\n        // Space bar (Keycode 32)\n        if (graphics_is_key_down(32)) {\n            mode = (mode + 1) % NUM_MODES;\n        }\n\n        // =========================================================\n        // Step 1: Render dynamic vector scene with Canvas 2D\n        // =========================================================\n        canvas_set_fill_style(\"#0f111a\");\n        canvas_fill_rect(0, 0, WIDTH, HEIGHT);\n\n        // Draw animated concentric color discs\n        for (int i = 5; i >= 1; i--) {\n            float r = i * 22.0f;\n            float cx = WIDTH / 2.0f + cosf(time_sec * 0.8f + i * 0.5f) * 45.0f;\n            float cy = HEIGHT / 2.0f + sinf(time_sec * 1.1f + i * 0.4f) * 30.0f;\n\n            canvas_begin_path();\n            canvas_arc(cx, cy, r, 0, 6.28318f, false);\n            if (i % 3 == 0) canvas_set_fill_style(\"#ff5370\");\n            else if (i % 3 == 1) canvas_set_fill_style(\"#82aaff\");\n            else canvas_set_fill_style(\"#c3e88d\");\n            canvas_fill();\n        }\n\n        // Draw rotating square\n        canvas_save();\n        canvas_translate(WIDTH / 2.0f, HEIGHT / 2.0f);\n        canvas_rotate(time_sec * 0.7f);\n        canvas_set_stroke_style(\"#ffcb6b\");\n        canvas_set_line_width(4.0f);\n        canvas_stroke_rect(-35, -35, 70, 70);\n        canvas_restore();\n\n        // Vector text in background scene\n        canvas_set_font(\"bold 16px sans-serif\");\n        canvas_set_fill_style(\"#f78c6c\");\n        canvas_fill_text(\"WASM-C-IDE\", 20, 40);\n\n        // =========================================================\n        // Step 2: Pixel-Level Manipulation & 2D Image Processing\n        // =========================================================\n        if (mode == 6) {\n            // Demonstrate canvas_get_image_data / canvas_put_image_data on a sub-region\n            int sub_w = 120, sub_h = 80;\n            int sub_x = 20, sub_y = 60;\n            static uint32_t sub_buffer[120 * 80];\n\n            canvas_get_image_data(sub_x, sub_y, sub_w, sub_h, sub_buffer);\n\n            // Invert colors inside sub-region in-place\n            for (int i = 0; i < sub_w * sub_h; i++) {\n                uint32_t p = sub_buffer[i];\n                sub_buffer[i] = PACK_RGBA(255 - PIXEL_R(p), 255 - PIXEL_G(p), 255 - PIXEL_B(p), 255);\n            }\n\n            // Blit inverted sub-region to the right side\n            canvas_put_image_data(WIDTH - sub_w - 20, sub_y, sub_w, sub_h, sub_buffer);\n\n            // Demonstrate canvas_set_pixel() by drawing a dotted grid\n            for (int gy = 160; gy < 220; gy += 4) {\n                for (int gx = 20; gx < 300; gx += 4) {\n                    canvas_set_pixel(gx, gy, PACK_RGBA(255, 235, 59, 255));\n                }\n            }\n        } else {\n            // Read full canvas framebuffer into C memory\n            canvas_get_pixels(src_pixels);\n\n            // Apply selected image filter\n            switch (mode) {\n                case 0: // Interactive Lens with Sobel Edges\n                    filter_sobel(src_pixels, dst_pixels);\n                    apply_lens(src_pixels, dst_pixels, dst_pixels, mouseX, mouseY, 45);\n                    canvas_put_pixels(dst_pixels);\n                    break;\n\n                case 1: // Interactive Lens with 3x3 Box Blur\n                    filter_box_blur(src_pixels, dst_pixels);\n                    apply_lens(src_pixels, dst_pixels, dst_pixels, mouseX, mouseY, 45);\n                    canvas_put_pixels(dst_pixels);\n                    break;\n\n                case 2: // Full Sobel Edge Detection\n                    filter_sobel(src_pixels, dst_pixels);\n                    canvas_put_pixels(dst_pixels);\n                    break;\n\n                case 3: // Full 3x3 Box Blur\n                    filter_box_blur(src_pixels, dst_pixels);\n                    canvas_put_pixels(dst_pixels);\n                    break;\n\n                case 4: // Full Grayscale & Contrast\n                    filter_grayscale(src_pixels, dst_pixels);\n                    canvas_put_pixels(dst_pixels);\n                    break;\n\n                case 5: // Full Invert Colors\n                    filter_invert(src_pixels, dst_pixels);\n                    canvas_put_pixels(dst_pixels);\n                    break;\n            }\n        }\n\n        // =========================================================\n        // Step 3: Overlay high-level Vector HUD on top of pixels\n        // =========================================================\n        // HUD Banner\n        canvas_set_fill_style(\"rgba(0, 0, 0, 0.75)\");\n        canvas_fill_rect(0, HEIGHT - 32, WIDTH, 32);\n\n        // Status text\n        char status_buf[128];\n        snprintf(status_buf, sizeof(status_buf), \"[%d/%d] %s\", mode + 1, NUM_MODES, MODE_NAMES[mode]);\n        canvas_set_font(\"12px sans-serif\");\n        canvas_set_fill_style(\"#ffffff\");\n        canvas_fill_text(status_buf, 10, HEIGHT - 18);\n\n        canvas_set_font(\"10px monospace\");\n        canvas_set_fill_style(\"#89ddff\");\n        snprintf(status_buf, sizeof(status_buf), \"Pos:(%d,%d) Click:Next\", mouseX, mouseY);\n        canvas_fill_text(status_buf, 10, HEIGHT - 6);\n\n        // Present canvas frame\n        canvas_present();\n\n        // 60 FPS frame pacing\n        graphics_wait_frame(60);\n    }\n\n    graphics_close();\n    return 0;\n}\n",
  "06_turtle_canvas.c": "#include <turtle.h>\n#include <turtle_backend_canvas_wasi.h>\n\n/**\n * 06_turtle_canvas.c - Turtle Graphics with Canvas-WASI Backend\n *\n * Demonstrates the default browser-hosted HTML5 Canvas 2D turtle graphics\n * powered by <turtle.h> and <turtle_backend_canvas_wasi.h>.\n *\n * Compilation:\n *   gcc 06_turtle_canvas.c -lturtle -o a.out\n *   ./a.out\n */\nint main(void) {\n    turtle_canvas_wasi_context_t ctx = {\n        .width = 800,\n        .height = 600,\n        .title = \"Turtle Graphics - Canvas WASI Demo\"\n    };\n\n    if (!turtle_begin(&ctx)) {\n        return 1;\n    }\n\n    /* Clear viewport to white */\n    turtle_clear(TURTLE_WHITE);\n\n    /* 6-color palette for vibrant star spiral */\n    const uint32_t colors[] = {\n        TURTLE_RED,\n        TURTLE_YELLOW,\n        TURTLE_GREEN,\n        TURTLE_CYAN,\n        TURTLE_BLUE,\n        TURTLE_MAGENTA\n    };\n    const int num_colors = sizeof(colors) / sizeof(colors[0]);\n\n    turtle_pen_stroke(2.5);\n\n    /* Draw progressive animated star spiral */\n    for (int i = 0; i < 60; i++) {\n        turtle_pen_color(colors[i % num_colors]);\n        turtle_forward(i * 4.0);\n        turtle_turn_right(144.0);\n        turtle_delay(35.0); /* 35ms progressive animation pacing */\n    }\n\n    turtle_end();\n    return 0;\n}\n",
  "07_turtle_raylib.c": "#include <turtle.h>\n#include <turtle_backend_raylib.h>\n\n/**\n * 07_turtle_raylib.c - Turtle Graphics with Raylib Backend\n *\n * Demonstrates the Raylib-backed turtle graphics subsystem powered by\n * <turtle.h> and <turtle_backend_raylib.h>. Requires Raylib support to be\n * enabled in Project Settings.\n *\n * Compilation:\n *   gcc 07_turtle_raylib.c -lturtle_raylib -lraylib -o a.out\n *   ./a.out\n */\nint main(void) {\n    turtle_raylib_context_t ctx = {\n        .width = 800,\n        .height = 600,\n        .title = \"Turtle Graphics - Raylib Demo\",\n        .target_fps = 60\n    };\n\n    if (!turtle_begin(&ctx)) {\n        return 1;\n    }\n\n    /* Clear canvas background to white */\n    turtle_clear(TURTLE_WHITE);\n\n    /* 6-color palette for geometric rosette */\n    const uint32_t colors[] = {\n        TURTLE_RED,\n        TURTLE_GREEN,\n        TURTLE_BLUE,\n        TURTLE_YELLOW,\n        TURTLE_MAGENTA,\n        TURTLE_CYAN\n    };\n    const int num_colors = sizeof(colors) / sizeof(colors[0]);\n\n    turtle_pen_stroke(2.0);\n\n    /* Draw progressive geometric rosette */\n    for (int i = 0; i < 72; i++) {\n        turtle_pen_color(colors[i % num_colors]);\n        turtle_forward(i * 3.5);\n        turtle_turn_left(59.0);\n        turtle_delay(25.0); /* 25ms progressive animation pacing */\n    }\n\n    turtle_end();\n    return 0;\n}\n",
  "08_ansi_terminal.c": "/*\n * 08_ansi_terminal.c - Comprehensive ANSI Escape Sequence & Screen Control Demo\n *\n * Demonstrates VT100 / ANSI escape sequence terminal capabilities in WebAssembly WASI:\n *   - Screen clearing & cursor positioning: \\033[2J, \\033[H, \\033[<r>;<c>H\n *   - Cursor visibility toggling: \\033[?25l (hide), \\033[?25h (show)\n *   - Text styling (SGR): Bold, Dim, Italic, Underline, Inverse, Strikethrough\n *   - 16-color ANSI palette and 256-color RGB spectrum bars\n *   - Structured multi-window TUI layout tailored for 80x24 detached terminal mode\n *   - In-place smooth animated progress bar and telemetry updates\n *\n * Compilation & Execution:\n *   gcc 08_ansi_terminal.c -o a.out\n *   ./a.out\n */\n\n#define _POSIX_C_SOURCE 200809L\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <string.h>\n#include <time.h>\n\n/* ANSI Escape Code Constants */\n#define ESC_RESET       \"\\033[0m\"\n#define ESC_BOLD        \"\\033[1m\"\n#define ESC_DIM         \"\\033[2m\"\n#define ESC_ITALIC      \"\\033[3m\"\n#define ESC_UNDERLINE   \"\\033[4m\"\n#define ESC_REVERSE     \"\\033[7m\"\n#define ESC_STRIKE      \"\\033[9m\"\n\n#define ESC_CLEAR_SCR   \"\\033[2J\"\n#define ESC_CLEAR_EOL   \"\\033[K\"\n#define ESC_CURSOR_HOME \"\\033[H\"\n#define ESC_HIDE_CURSOR \"\\033[?25l\"\n#define ESC_SHOW_CURSOR \"\\033[?25h\"\n\n/* Terminal Cursor Movement Helper (ANSI CUP - Cursor Position) */\nstatic void move_to(int row, int col) {\n    printf(\"\\033[%d;%dH\", row, col);\n}\n\n/* Draw a styled box with single or double line characters */\nstatic void draw_box(int top, int left, int width, int height, const char *title, int double_border) {\n    const char *tl = double_border ? \"╔\" : \"┌\";\n    const char *tr = double_border ? \"╗\" : \"┐\";\n    const char *bl = double_border ? \"╚\" : \"└\";\n    const char *br = double_border ? \"╝\" : \"┘\";\n    const char *hz = double_border ? \"═\" : \"─\";\n    const char *vt = double_border ? \"║\" : \"│\";\n\n    /* Top border */\n    move_to(top, left);\n    printf(\"%s\", tl);\n    for (int i = 0; i < width - 2; i++) {\n        printf(\"%s\", hz);\n    }\n    printf(\"%s\", tr);\n\n    /* Side borders */\n    for (int r = 1; r < height - 1; r++) {\n        move_to(top + r, left);\n        printf(\"%s\", vt);\n        move_to(top + r, left + width - 1);\n        printf(\"%s\", vt);\n    }\n\n    /* Bottom border */\n    move_to(top + height - 1, left);\n    printf(\"%s\", bl);\n    for (int i = 0; i < width - 2; i++) {\n        printf(\"%s\", hz);\n    }\n    printf(\"%s\", br);\n\n    /* Optional Title */\n    if (title && strlen(title) > 0) {\n        move_to(top, left + 3);\n        printf(\"┤ \" ESC_BOLD \"%s\" ESC_RESET \" ├\", title);\n    }\n}\n\n/* Sleep milliseconds wrapper using standard POSIX nanosleep */\nstatic void delay_ms(int ms) {\n    struct timespec ts;\n    ts.tv_sec = ms / 1000;\n    ts.tv_nsec = (long)(ms % 1000) * 1000000L;\n    nanosleep(&ts, NULL);\n}\n\nint main(void) {\n    /* 1. Initialize screen: Clear display and hide hardware cursor */\n    printf(ESC_CLEAR_SCR ESC_CURSOR_HOME ESC_HIDE_CURSOR);\n    fflush(stdout);\n\n    /* 2. Outer Window Frame (80x24 geometry) */\n    printf(\"\\033[38;5;39m\"); /* Bright Cyan Border */\n    draw_box(1, 1, 80, 24, \"WASM-C-IDE :: ANSI SCREEN CONTROL DEMO (80x24)\", 1);\n    printf(ESC_RESET);\n\n    /* 3. Top Banner & Subtitle */\n    move_to(2, 4);\n    printf(ESC_BOLD \"\\033[38;5;220mDEC VT100 / xterm.js Showcase\" ESC_RESET);\n    move_to(2, 62);\n    printf(ESC_DIM \"Geometry: 80x24\" ESC_RESET);\n\n    /* 4. Left Pane: System Telemetry (rows 4 to 14, left 3, width 36, ends col 38) */\n    printf(\"\\033[38;5;75m\");\n    draw_box(4, 3, 36, 11, \"Telemetry & Host\", 0);\n    printf(ESC_RESET);\n\n    move_to(6, 5);\n    printf(ESC_BOLD \"Architecture:\" ESC_RESET \" wasm32-wasip1\");\n    move_to(7, 5);\n    printf(ESC_BOLD \"WASI Runtime:\" ESC_RESET \" Zero-MemFS VFS\");\n    move_to(8, 5);\n    printf(ESC_BOLD \"Terminal:    \" ESC_RESET \" xterm.js 5.5\");\n    move_to(9, 5);\n    printf(ESC_BOLD \"Color Mode:  \" ESC_RESET \" 24-bit TrueColor\");\n    move_to(10, 5);\n    printf(ESC_BOLD \"Layout:      \" ESC_RESET \" Detached Floating\");\n    move_to(11, 5);\n    printf(ESC_BOLD \"Sync Stdin:  \" ESC_RESET \" SharedArrayBuffer\");\n    move_to(12, 5);\n    printf(ESC_BOLD \"Virtual VFS: \" ESC_RESET \" In-Memory IDB\");\n\n    /* 5. Right Pane: ANSI Text Attributes & 16-Color Palette (rows 4 to 14, left 41, width 37, ends col 77) */\n    printf(\"\\033[38;5;178m\");\n    draw_box(4, 41, 37, 11, \"SGR Styles & ANSI 16 Colors\", 0);\n    printf(ESC_RESET);\n\n    move_to(6, 43);\n    printf(ESC_BOLD \"Bold\" ESC_RESET \"  \" ESC_DIM \"Dim\" ESC_RESET \"  \"\n           ESC_ITALIC \"Italic\" ESC_RESET \"  \" ESC_UNDERLINE \"Underline\" ESC_RESET \"  \"\n           ESC_REVERSE \"Inv\" ESC_RESET);\n\n    move_to(8, 43);\n    printf(ESC_BOLD \"Standard 8 Colors:\" ESC_RESET);\n    move_to(9, 43);\n    for (int i = 0; i < 8; i++) {\n        printf(\"\\033[4%dm  \", i);\n    }\n    printf(ESC_RESET \" (30-37)\");\n\n    move_to(11, 43);\n    printf(ESC_BOLD \"High-Intensity 8 Colors:\" ESC_RESET);\n    move_to(12, 43);\n    for (int i = 0; i < 8; i++) {\n        printf(\"\\033[10%dm  \", i);\n    }\n    printf(ESC_RESET \" (90-97)\");\n\n    /* 6. Middle: 256-Color Gradient Bar (row 15, ends at col 77) */\n    move_to(15, 3);\n    printf(ESC_BOLD \"256 Colors: \" ESC_RESET);\n    for (int i = 16; i <= 78; i++) {\n        printf(\"\\033[48;5;%dm \", i);\n    }\n    printf(ESC_RESET);\n\n    /* 7. Bottom Pane: In-Place Live Screen Updates & Animation (rows 16 to 22, left 3, width 75, ends col 77) */\n    printf(\"\\033[38;5;113m\");\n    draw_box(16, 3, 75, 6, \"In-Place Live Screen Animation (Flicker-Free)\", 0);\n    printf(ESC_RESET);\n\n    move_to(18, 5);\n    printf(ESC_BOLD \"Task Processing: \" ESC_RESET \"Rendering procedural ANSI frame buffer...\");\n\n    /* 8. Animated Progress Bar Simulation */\n    const int bar_width = 46;\n    for (int percent = 0; percent <= 100; percent += 5) {\n        int filled = (percent * bar_width) / 100;\n\n        move_to(19, 5);\n        printf(\"[\");\n        printf(\"\\033[38;5;48m\");\n        for (int i = 0; i < filled; i++) {\n            printf(\"━\");\n        }\n        printf(\"\\033[38;5;238m\");\n        for (int i = filled; i < bar_width; i++) {\n            printf(\"─\");\n        }\n        printf(ESC_RESET \"] %3d%%  \", percent);\n\n        /* Moving spinner indicator */\n        const char *spinner = \"|/-\\\\\";\n        printf(\"\\033[38;5;226m%c\\033[0m\", spinner[(percent / 5) % 4]);\n\n        /* Dynamic status message */\n        move_to(20, 5);\n        printf(ESC_DIM \"Buffer coordinate updates: row 19, col %-2d | ESC count: %-3d\" ESC_RESET,\n               5 + filled, 120 + percent * 4);\n\n        fflush(stdout);\n        delay_ms(30);\n    }\n\n    move_to(20, 5);\n    printf(ESC_BOLD \"\\033[38;5;46m[OK] Processing Complete! All 80x24 coordinates rendered cleanly.\" ESC_CLEAR_EOL ESC_RESET);\n    printf(\"\\033[38;5;113m\");\n    move_to(20, 77);\n    printf(\"│\" ESC_RESET);\n\n    /* 9. Footer Prompt */\n    move_to(23, 4);\n    printf(ESC_BOLD \"Press Enter to exit demo...\" ESC_RESET);\n    fflush(stdout);\n\n    /* Wait for user input or Enter */\n    getchar();\n\n    /* 10. Clean exit: restore cursor visibility, reset styles, and park cursor at bottom */\n    printf(ESC_RESET ESC_SHOW_CURSOR);\n    move_to(24, 1);\n    printf(\"\\n\");\n    fflush(stdout);\n\n    return 0;\n}\n",
  "09_sqlite_database.c": "/*\n * 09_sqlite_database.c - SQLite 3 In-Browser Database Operations & CLI Demo\n *\n * This example demonstrates:\n *   1. Opening an embedded SQLite database in /workspace/demo.db\n *   2. Creating a relational table with schema constraints\n *   3. Inserting rows using prepared statements and parameterized bindings\n *   4. Querying records with sqlite3_prepare_v2, sqlite3_step, and sqlite3_column_*\n *   5. Formatted tabular console output\n *\n * Compilation & Execution:\n *   gcc 09_sqlite_database.c -lsqlite3 -o demo\n *   ./demo\n *\n * Terminal Inspection:\n *   You can inspect and query demo.db directly using the built-in SQLite CLI:\n *   sqlite3 demo.db \"SELECT * FROM learners;\"\n *   sqlite3 demo.db \".schema\"\n */\n\n#include <stdio.h>\n#include <stdlib.h>\n#include <sqlite3.h>\n\nint main(void) {\n    sqlite3 *db = NULL;\n    char *err_msg = NULL;\n    int rc;\n\n    printf(\"==========================================\\n\");\n    printf(\"   SQLite 3 WASI Preview 1 Database Demo  \\n\");\n    printf(\"==========================================\\n\\n\");\n    printf(\"SQLite Version: %s\\n\\n\", sqlite3_libversion());\n\n    // 1. Open database file in /workspace\n    const char *db_path = \"demo.db\";\n    printf(\"[1] Opening database '%s'...\\n\", db_path);\n    rc = sqlite3_open(db_path, &db);\n    if (rc != SQLITE_OK) {\n        fprintf(stderr, \"Error opening database: %s\\n\", sqlite3_errmsg(db));\n        sqlite3_close(db);\n        return 1;\n    }\n    printf(\"    Database opened successfully.\\n\\n\");\n\n    // 2. Create table\n    printf(\"[2] Creating table 'learners'...\\n\");\n    const char *sql_create = \n        \"CREATE TABLE IF NOT EXISTS learners (\"\n        \"  id INTEGER PRIMARY KEY AUTOINCREMENT,\"\n        \"  name TEXT NOT NULL,\"\n        \"  track TEXT NOT NULL,\"\n        \"  score REAL NOT NULL\"\n        \");\";\n\n    rc = sqlite3_exec(db, sql_create, NULL, NULL, &err_msg);\n    if (rc != SQLITE_OK) {\n        fprintf(stderr, \"SQL error: %s\\n\", err_msg);\n        sqlite3_free(err_msg);\n        sqlite3_close(db);\n        return 1;\n    }\n    printf(\"    Table 'learners' is ready.\\n\\n\");\n\n    // 3. Insert records using prepared statements\n    printf(\"[3] Inserting student records via prepared statements...\\n\");\n    const char *sql_insert = \"INSERT INTO learners (name, track, score) VALUES (?, ?, ?);\";\n    sqlite3_stmt *stmt = NULL;\n\n    rc = sqlite3_prepare_v2(db, sql_insert, -1, &stmt, NULL);\n    if (rc != SQLITE_OK) {\n        fprintf(stderr, \"Failed to prepare insert statement: %s\\n\", sqlite3_errmsg(db));\n        sqlite3_close(db);\n        return 1;\n    }\n\n    struct Student {\n        const char *name;\n        const char *track;\n        double score;\n    } students[] = {\n        { \"Alice Chen\",   \"Systems Programming\", 98.5 },\n        { \"Bob Smith\",    \"Computer Graphics\",   92.0 },\n        { \"Charlie Davis\",\"Database Internals\",  95.5 },\n        { \"Diana Prince\", \"WebAssembly & WASI\",  99.0 },\n    };\n    int count = sizeof(students) / sizeof(students[0]);\n\n    for (int i = 0; i < count; i++) {\n        sqlite3_reset(stmt);\n        sqlite3_bind_text(stmt, 1, students[i].name, -1, SQLITE_STATIC);\n        sqlite3_bind_text(stmt, 2, students[i].track, -1, SQLITE_STATIC);\n        sqlite3_bind_double(stmt, 3, students[i].score);\n\n        if (sqlite3_step(stmt) != SQLITE_DONE) {\n            fprintf(stderr, \"Execution failed: %s\\n\", sqlite3_errmsg(db));\n        } else {\n            printf(\"    + Inserted: %-14s | %-21s | %5.1f\\n\",\n                   students[i].name, students[i].track, students[i].score);\n        }\n    }\n    sqlite3_finalize(stmt);\n    printf(\"\\n\");\n\n    // 4. Query and display records\n    printf(\"[4] Querying learners with score >= 95.0:\\n\");\n    printf(\"    ----------------------------------------------------------\\n\");\n    printf(\"    %-4s | %-16s | %-22s | %-5s\\n\", \"ID\", \"Name\", \"Track\", \"Score\");\n    printf(\"    ----------------------------------------------------------\\n\");\n\n    const char *sql_select = \"SELECT id, name, track, score FROM learners WHERE score >= ? ORDER BY score DESC;\";\n    rc = sqlite3_prepare_v2(db, sql_select, -1, &stmt, NULL);\n    if (rc == SQLITE_OK) {\n        sqlite3_bind_double(stmt, 1, 95.0);\n        while (sqlite3_step(stmt) == SQLITE_ROW) {\n            int id = sqlite3_column_int(stmt, 0);\n            const unsigned char *name = sqlite3_column_text(stmt, 1);\n            const unsigned char *track = sqlite3_column_text(stmt, 2);\n            double score = sqlite3_column_double(stmt, 3);\n\n            printf(\"    #%-3d | %-16s | %-22s | %5.1f\\n\", id, name, track, score);\n        }\n        sqlite3_finalize(stmt);\n    }\n    printf(\"    ----------------------------------------------------------\\n\\n\");\n\n    // 5. Aggregate statistics\n    printf(\"[5] Calculating class statistics:\\n\");\n    const char *sql_stats = \"SELECT COUNT(*), AVG(score), MAX(score), MIN(score) FROM learners;\";\n    rc = sqlite3_prepare_v2(db, sql_stats, -1, &stmt, NULL);\n    if (rc == SQLITE_OK && sqlite3_step(stmt) == SQLITE_ROW) {\n        int total = sqlite3_column_int(stmt, 0);\n        double avg = sqlite3_column_double(stmt, 1);\n        double max = sqlite3_column_double(stmt, 2);\n        double min = sqlite3_column_double(stmt, 3);\n\n        printf(\"    Total students: %d\\n\", total);\n        printf(\"    Average score:  %.2f\\n\", avg);\n        printf(\"    Highest score:  %.1f\\n\", max);\n        printf(\"    Lowest score:   %.1f\\n\", min);\n        sqlite3_finalize(stmt);\n    }\n    printf(\"\\n\");\n\n    // 6. Close database\n    printf(\"[6] Closing database connection...\\n\");\n    sqlite3_close(db);\n    printf(\"    Database connection closed cleanly.\\n\");\n    printf(\"\\n[Hint] In xterm, inspect the database with:\\n\");\n    printf(\"       sqlite3 demo.db \\\"SELECT * FROM learners;\\\"\\n\");\n\n    return 0;\n}\n",
  "10_raylib_gui_audio.c": "/*\n * 10_raylib_gui_audio.c - Interactive Raylib GUI, Waveform Animation & Audio Synthesizer\n *\n * Demonstrates:\n *   1. Immediate-mode GUI controls with raygui.h (buttons, sliders, checkboxes, group boxes)\n *   2. Procedural audio synthesis without external files via Raylib Audio (InitAudioDevice, LoadSoundFromWave, PlaySound)\n *   3. Real-time dynamic audio visualization (harmonic equalizer spectrum, peak gravity meters, orbital particles)\n *   4. Audio-driven interactive shockwave ripples and pulsating core animation\n *\n * Compilation & Execution in IDE:\n *   gcc 10_raylib_gui_audio.c -lraylib -o a.out\n *   ./a.out\n *\n * Controls:\n *   - Click GUI buttons [Chime], [Laser], [Pop], [Synth] or press keys [1], [2], [3], [4]\n *   - Click directly on the pulsating central orb to trigger interactive audio\n *   - Adjust Volume, Pitch, and Animation Speed using immediate-mode sliders\n *   - Toggle Equalizer Spectrum and Orbital Particles using checkboxes\n *   - Switch color themes between Cyan, Sunset, and Emerald\n */\n\n#include \"raylib.h\"\n\n#define RAYGUI_IMPLEMENTATION\n#include \"raygui.h\"\n\n#include <math.h>\n#include <stdlib.h>\n\n#define MAX_SHOCKWAVES 8\n#define NUM_SPECTRUM_BARS 16\n#define NUM_ORBITAL_PARTICLES 24\n\ntypedef struct {\n    Vector2 center;\n    float radius;\n    float maxRadius;\n    float alpha;\n    bool active;\n    Color color;\n} Shockwave;\n\ntypedef struct {\n    float height;\n    float targetHeight;\n    float peakHeight;\n    float peakVelocity;\n} SpectrumBar;\n\ntypedef enum {\n    THEME_CYAN = 0,\n    THEME_SUNSET,\n    THEME_EMERALD\n} ColorTheme;\n\n// --- Procedural Audio Generators ---\n\nstatic Sound GenerateChime(void) {\n    const int sampleRate = 44100;\n    const int frameCount = (int)(sampleRate * 1.1f);\n    short *samples = (short *)malloc(frameCount * sizeof(short));\n    if (!samples) return (Sound){ 0 };\n\n    for (int i = 0; i < frameCount; i++) {\n        float t = (float)i / (float)sampleRate;\n        float decay = expf(-3.5f * t);\n        // Harmonic major chord: C5 (523.25), E5 (659.25), G5 (783.99), C6 (1046.50)\n        float tone = sinf(2.0f * PI * 523.25f * t) * 0.40f +\n                     sinf(2.0f * PI * 659.25f * t) * 0.30f +\n                     sinf(2.0f * PI * 783.99f * t) * 0.20f +\n                     sinf(2.0f * PI * 1046.50f * t) * 0.10f;\n        samples[i] = (short)(tone * decay * 28000.0f);\n    }\n\n    Wave wave = {\n        .frameCount = frameCount,\n        .sampleRate = sampleRate,\n        .sampleSize = 16,\n        .channels = 1,\n        .data = samples\n    };\n    Sound sound = LoadSoundFromWave(wave);\n    UnloadWave(wave);\n    return sound;\n}\n\nstatic Sound GenerateLaser(void) {\n    const int sampleRate = 44100;\n    const float duration = 0.28f;\n    const int frameCount = (int)(sampleRate * duration);\n    short *samples = (short *)malloc(frameCount * sizeof(short));\n    if (!samples) return (Sound){ 0 };\n\n    float phase = 0.0f;\n    for (int i = 0; i < frameCount; i++) {\n        float t = (float)i / (float)sampleRate;\n        float progress = t / duration;\n        float freq = 1100.0f * (1.0f - progress * 0.78f);\n        phase += 2.0f * PI * freq * (1.0f / (float)sampleRate);\n        float env = 1.0f - progress;\n        float tone = sinf(phase);\n        samples[i] = (short)(tone * env * 28000.0f);\n    }\n\n    Wave wave = {\n        .frameCount = frameCount,\n        .sampleRate = sampleRate,\n        .sampleSize = 16,\n        .channels = 1,\n        .data = samples\n    };\n    Sound sound = LoadSoundFromWave(wave);\n    UnloadWave(wave);\n    return sound;\n}\n\nstatic Sound GeneratePop(void) {\n    const int sampleRate = 44100;\n    const float duration = 0.22f;\n    const int frameCount = (int)(sampleRate * duration);\n    short *samples = (short *)malloc(frameCount * sizeof(short));\n    if (!samples) return (Sound){ 0 };\n\n    float phase = 0.0f;\n    for (int i = 0; i < frameCount; i++) {\n        float t = (float)i / (float)sampleRate;\n        float progress = t / duration;\n        float freq = 280.0f * expf(-14.0f * progress) + 70.0f;\n        phase += 2.0f * PI * freq * (1.0f / (float)sampleRate);\n        float env = expf(-12.0f * progress);\n        float tone = sinf(phase) + 0.25f * sinf(phase * 2.0f);\n        samples[i] = (short)(tone * env * 30000.0f);\n    }\n\n    Wave wave = {\n        .frameCount = frameCount,\n        .sampleRate = sampleRate,\n        .sampleSize = 16,\n        .channels = 1,\n        .data = samples\n    };\n    Sound sound = LoadSoundFromWave(wave);\n    UnloadWave(wave);\n    return sound;\n}\n\nstatic Sound GenerateSynth(void) {\n    const int sampleRate = 44100;\n    const float duration = 0.75f;\n    const int frameCount = (int)(sampleRate * duration);\n    short *samples = (short *)malloc(frameCount * sizeof(short));\n    if (!samples) return (Sound){ 0 };\n\n    float phase = 0.0f;\n    for (int i = 0; i < frameCount; i++) {\n        float t = (float)i / (float)sampleRate;\n        float vibrato = sinf(2.0f * PI * 5.5f * t) * 9.0f;\n        float freq = 440.0f + vibrato;\n        phase += 2.0f * PI * freq * (1.0f / (float)sampleRate);\n        float env = (t < 0.04f) ? (t / 0.04f) : expf(-2.8f * (t - 0.04f));\n        float tone = sinf(phase) * 0.70f + sinf(2.0f * phase) * 0.20f + sinf(3.0f * phase) * 0.10f;\n        samples[i] = (short)(tone * env * 26000.0f);\n    }\n\n    Wave wave = {\n        .frameCount = frameCount,\n        .sampleRate = sampleRate,\n        .sampleSize = 16,\n        .channels = 1,\n        .data = samples\n    };\n    Sound sound = LoadSoundFromWave(wave);\n    UnloadWave(wave);\n    return sound;\n}\n\nint main(void) {\n    const int screenWidth = 800;\n    const int screenHeight = 450;\n\n    InitWindow(screenWidth, screenHeight, \"raylib [gui + audio + animation] Synthesizer Demo\");\n    SetTargetFPS(60);\n\n    InitAudioDevice();\n\n    Sound sndChime = GenerateChime();\n    Sound sndLaser = GenerateLaser();\n    Sound sndPop = GeneratePop();\n    Sound sndSynth = GenerateSynth();\n\n    float masterVolume = 0.80f;\n    float soundPitch = 1.0f;\n    float animSpeed = 1.0f;\n    bool showEqualizer = true;\n    bool showOrbital = true;\n    ColorTheme activeTheme = THEME_CYAN;\n\n    Shockwave shockwaves[MAX_SHOCKWAVES] = { 0 };\n    SpectrumBar bars[NUM_SPECTRUM_BARS] = { 0 };\n\n    float pulseIntensity = 0.0f;\n    const char *lastPlayedSound = \"None\";\n\n    Vector2 stageCenter = { 555.0f, 215.0f };\n    Rectangle stageRect = { 325, 50, 460, 385 };\n\n    while (!WindowShouldClose()) {\n        float dt = GetFrameTime();\n        float time = (float)GetTime();\n\n        SetSoundVolume(sndChime, masterVolume);\n        SetSoundVolume(sndLaser, masterVolume);\n        SetSoundVolume(sndPop, masterVolume);\n        SetSoundVolume(sndSynth, masterVolume);\n\n        SetSoundPitch(sndChime, soundPitch);\n        SetSoundPitch(sndLaser, soundPitch);\n        SetSoundPitch(sndPop, soundPitch);\n        SetSoundPitch(sndSynth, soundPitch);\n\n        Color primaryColor;\n        Color secondaryColor;\n        Color accentColor;\n\n        switch (activeTheme) {\n            case THEME_SUNSET:\n                primaryColor = (Color){ 255, 120, 40, 255 };\n                secondaryColor = (Color){ 240, 60, 90, 255 };\n                accentColor = (Color){ 255, 210, 80, 255 };\n                break;\n            case THEME_EMERALD:\n                primaryColor = (Color){ 20, 210, 140, 255 };\n                secondaryColor = (Color){ 10, 160, 180, 255 };\n                accentColor = (Color){ 140, 240, 100, 255 };\n                break;\n            case THEME_CYAN:\n            default:\n                primaryColor = (Color){ 30, 190, 255, 255 };\n                secondaryColor = (Color){ 140, 60, 255, 255 };\n                accentColor = (Color){ 80, 240, 255, 255 };\n                break;\n        }\n\n        bool triggerChime = false;\n        bool triggerLaser = false;\n        bool triggerPop = false;\n        bool triggerSynth = false;\n\n        if (IsKeyPressed(KEY_ONE)) triggerChime = true;\n        if (IsKeyPressed(KEY_TWO)) triggerLaser = true;\n        if (IsKeyPressed(KEY_THREE)) triggerPop = true;\n        if (IsKeyPressed(KEY_FOUR)) triggerSynth = true;\n\n        if (IsMouseButtonPressed(MOUSE_BUTTON_LEFT)) {\n            Vector2 mPos = GetMousePosition();\n            if (CheckCollisionPointCircle(mPos, stageCenter, 50.0f)) {\n                triggerChime = true;\n            }\n        }\n\n        #define SPAWN_RIPPLE(col) do { \\\n            for (int r = 0; r < MAX_SHOCKWAVES; r++) { \\\n                if (!shockwaves[r].active) { \\\n                    shockwaves[r].active = true; \\\n                    shockwaves[r].center = stageCenter; \\\n                    shockwaves[r].radius = 28.0f; \\\n                    shockwaves[r].maxRadius = 160.0f; \\\n                    shockwaves[r].alpha = 0.95f; \\\n                    shockwaves[r].color = col; \\\n                    break; \\\n                } \\\n            } \\\n            pulseIntensity = 1.0f; \\\n        } while (0)\n\n        if (triggerChime) {\n            PlaySound(sndChime);\n            lastPlayedSound = \"Chime (Harmonic)\";\n            SPAWN_RIPPLE(accentColor);\n        } else if (triggerLaser) {\n            PlaySound(sndLaser);\n            lastPlayedSound = \"Laser (Sweep)\";\n            SPAWN_RIPPLE(secondaryColor);\n        } else if (triggerPop) {\n            PlaySound(sndPop);\n            lastPlayedSound = \"Pop (Percussion)\";\n            SPAWN_RIPPLE(primaryColor);\n        } else if (triggerSynth) {\n            PlaySound(sndSynth);\n            lastPlayedSound = \"Synth (Vibrato)\";\n            SPAWN_RIPPLE(Fade(accentColor, 0.8f));\n        }\n\n        for (int r = 0; r < MAX_SHOCKWAVES; r++) {\n            if (shockwaves[r].active) {\n                shockwaves[r].radius += 180.0f * animSpeed * dt;\n                shockwaves[r].alpha -= 1.4f * animSpeed * dt;\n                if (shockwaves[r].alpha <= 0.0f || shockwaves[r].radius >= shockwaves[r].maxRadius) {\n                    shockwaves[r].active = false;\n                }\n            }\n        }\n\n        pulseIntensity -= 2.2f * dt;\n        if (pulseIntensity < 0.0f) pulseIntensity = 0.0f;\n\n        for (int b = 0; b < NUM_SPECTRUM_BARS; b++) {\n            float phase = (float)b * 0.45f;\n            float harmonic = sinf(time * animSpeed * 4.0f + phase) * 0.5f + 0.5f;\n            float harmonic2 = sinf(time * animSpeed * 7.5f - phase * 1.5f) * 0.3f;\n            float target = (harmonic + harmonic2) * 65.0f + 12.0f;\n            target += pulseIntensity * (70.0f + sinf((float)b) * 20.0f);\n\n            bars[b].targetHeight = target;\n            bars[b].height += (bars[b].targetHeight - bars[b].height) * 12.0f * dt;\n\n            if (bars[b].height > bars[b].peakHeight) {\n                bars[b].peakHeight = bars[b].height;\n                bars[b].peakVelocity = 0.0f;\n            } else {\n                bars[b].peakVelocity += 250.0f * dt;\n                bars[b].peakHeight -= bars[b].peakVelocity * dt;\n                if (bars[b].peakHeight < bars[b].height) {\n                    bars[b].peakHeight = bars[b].height;\n                }\n            }\n        }\n\n        BeginDrawing();\n            ClearBackground((Color){ 16, 20, 28, 255 });\n\n            DrawText(\"RAYLIB AUDIO & GUI SYNTHESIZER\", 20, 15, 20, RAYWHITE);\n            DrawText(\"raygui immediate-mode controls, procedural Web Audio, and multi-tier animation\", 360, 18, 12, GRAY);\n\n            // Left Panel: Group 1 - Sound FX & Trigger Deck\n            GuiGroupBox((Rectangle){ 15, 50, 295, 180 }, \"Audio Synthesizer & FX\");\n\n            if (GuiButton((Rectangle){ 25, 75, 130, 32 }, \"#131#Chime [1]\")) {\n                PlaySound(sndChime);\n                lastPlayedSound = \"Chime (Harmonic)\";\n                SPAWN_RIPPLE(accentColor);\n            }\n            if (GuiButton((Rectangle){ 165, 75, 135, 32 }, \"#134#Laser [2]\")) {\n                PlaySound(sndLaser);\n                lastPlayedSound = \"Laser (Sweep)\";\n                SPAWN_RIPPLE(secondaryColor);\n            }\n            if (GuiButton((Rectangle){ 25, 115, 130, 32 }, \"#133#Pop [3]\")) {\n                PlaySound(sndPop);\n                lastPlayedSound = \"Pop (Percussion)\";\n                SPAWN_RIPPLE(primaryColor);\n            }\n            if (GuiButton((Rectangle){ 165, 115, 135, 32 }, \"#138#Synth [4]\")) {\n                PlaySound(sndSynth);\n                lastPlayedSound = \"Synth (Vibrato)\";\n                SPAWN_RIPPLE(Fade(accentColor, 0.8f));\n            }\n\n            GuiLabel((Rectangle){ 25, 158, 60, 20 }, \"Volume:\");\n            (void)GuiSlider((Rectangle){ 85, 158, 145, 20 }, \"0%\", \"100%\", &masterVolume, 0.0f, 1.0f);\n            DrawText(TextFormat(\"%.0f%%\", masterVolume * 100.0f), 245, 160, 13, RAYWHITE);\n\n            GuiLabel((Rectangle){ 25, 192, 60, 20 }, \"Pitch:\");\n            (void)GuiSlider((Rectangle){ 85, 192, 145, 20 }, \"0.5x\", \"2.0x\", &soundPitch, 0.5f, 2.0f);\n            DrawText(TextFormat(\"%.2fx\", soundPitch), 245, 194, 13, RAYWHITE);\n\n            // Left Panel: Group 2 - Visualizer & Animation Controls\n            GuiGroupBox((Rectangle){ 15, 245, 295, 190 }, \"Animation & Themes\");\n\n            (void)GuiCheckBox((Rectangle){ 25, 272, 18, 18 }, \"Spectrum Equalizer\", &showEqualizer);\n            (void)GuiCheckBox((Rectangle){ 165, 272, 18, 18 }, \"Orbital Particles\", &showOrbital);\n\n            GuiLabel((Rectangle){ 25, 308, 60, 20 }, \"Speed:\");\n            (void)GuiSlider((Rectangle){ 85, 308, 145, 20 }, \"0.5x\", \"3.0x\", &animSpeed, 0.5f, 3.0f);\n            DrawText(TextFormat(\"%.1fx\", animSpeed), 245, 310, 13, RAYWHITE);\n\n            GuiLabel((Rectangle){ 25, 345, 60, 20 }, \"Themes:\");\n            if (GuiButton((Rectangle){ 85, 342, 65, 26 }, \"Cyan\")) activeTheme = THEME_CYAN;\n            if (GuiButton((Rectangle){ 155, 342, 65, 26 }, \"Sunset\")) activeTheme = THEME_SUNSET;\n            if (GuiButton((Rectangle){ 225, 342, 65, 26 }, \"Emerald\")) activeTheme = THEME_EMERALD;\n\n            DrawText(\"Audio State:\", 25, 385, 13, GRAY);\n            DrawText(IsAudioDeviceReady() ? \"READY (Web Audio)\" : \"INACTIVE\", 110, 385, 13, GREEN);\n            DrawText(TextFormat(\"Last Played: %s\", lastPlayedSound), 25, 408, 13, accentColor);\n\n            // Right Stage: Live Interactive Visualizer\n            GuiGroupBox(stageRect, \"Interactive Visualizer Stage\");\n            DrawRectangleRec((Rectangle){ 326, 65, 458, 368 }, (Color){ 10, 12, 18, 255 });\n\n            // 1. Shockwaves\n            for (int r = 0; r < MAX_SHOCKWAVES; r++) {\n                if (shockwaves[r].active) {\n                    DrawCircleLines((int)shockwaves[r].center.x, (int)shockwaves[r].center.y, shockwaves[r].radius, Fade(shockwaves[r].color, shockwaves[r].alpha));\n                    DrawCircleLines((int)shockwaves[r].center.x, (int)shockwaves[r].center.y, shockwaves[r].radius + 2.0f, Fade(shockwaves[r].color, shockwaves[r].alpha * 0.5f));\n                }\n            }\n\n            // 2. Orbital Particles\n            if (showOrbital) {\n                float baseR = 85.0f + pulseIntensity * 25.0f;\n                for (int p = 0; p < NUM_ORBITAL_PARTICLES; p++) {\n                    float theta = time * animSpeed * 1.5f + (float)p * (2.0f * PI / (float)NUM_ORBITAL_PARTICLES);\n                    float r = baseR + sinf(theta * 3.0f + time * 2.0f) * 12.0f;\n                    float px = stageCenter.x + cosf(theta) * r;\n                    float py = stageCenter.y + sinf(theta) * r;\n                    float pSize = 3.0f + sinf(theta * 2.0f) * 1.5f + pulseIntensity * 2.0f;\n\n                    DrawCircle((int)px, (int)py, pSize, Fade(primaryColor, 0.85f));\n                    DrawLine((int)stageCenter.x, (int)stageCenter.y, (int)px, (int)py, Fade(secondaryColor, 0.12f));\n                }\n            }\n\n            // 3. Central Core Orb\n            float coreRadius = 36.0f + sinf(time * animSpeed * 3.0f) * 5.0f + pulseIntensity * 16.0f;\n            DrawCircleV(stageCenter, coreRadius + 10.0f, Fade(primaryColor, 0.15f));\n            DrawCircleV(stageCenter, coreRadius + 4.0f, Fade(primaryColor, 0.35f));\n            DrawCircleV(stageCenter, coreRadius, primaryColor);\n            DrawCircleV(stageCenter, coreRadius * 0.55f, RAYWHITE);\n            DrawText(\"CLICK\", (int)stageCenter.x - 18, (int)stageCenter.y - 6, 11, DARKBLUE);\n\n            // 4. Equalizer Spectrum Bars\n            if (showEqualizer) {\n                int barW = 18;\n                int barGap = 8;\n                int totalW = NUM_SPECTRUM_BARS * barW + (NUM_SPECTRUM_BARS - 1) * barGap;\n                int startX = (int)(stageRect.x + (stageRect.width - totalW) / 2.0f);\n                int baseY = (int)(stageRect.y + stageRect.height - 20);\n\n                for (int b = 0; b < NUM_SPECTRUM_BARS; b++) {\n                    int bx = startX + b * (barW + barGap);\n                    int bh = (int)bars[b].height;\n                    int by = baseY - bh;\n\n                    Color barCol = Fade(primaryColor, 0.75f + ((float)b / (float)NUM_SPECTRUM_BARS) * 0.25f);\n                    DrawRectangle(bx, by, barW, bh, barCol);\n                    DrawRectangleLines(bx, by, barW, bh, Fade(RAYWHITE, 0.3f));\n\n                    // Peak cap line\n                    int peakY = baseY - (int)bars[b].peakHeight;\n                    DrawRectangle(bx - 1, peakY - 3, barW + 2, 3, accentColor);\n                }\n            }\n\n            DrawText(TextFormat(\"FPS: %i\", GetFPS()), 725, 75, 12, GRAY);\n            DrawText(\"Keys [1..4] / Click Orb\", 625, 412, 12, GRAY);\n\n        EndDrawing();\n    }\n\n    UnloadSound(sndChime);\n    UnloadSound(sndLaser);\n    UnloadSound(sndPop);\n    UnloadSound(sndSynth);\n\n    CloseAudioDevice();\n    CloseWindow();\n\n    return 0;\n}\n"
};
